public static class InviteEndpoints
{
    public static void MapAcceptEndpoint(IEndpointRouteBuilder routes)
    {
        routes.MapPost("/invites/{token}/accept",
            async (
                string token,
                HttpContext ctx,
                IInvitationService invitationService,
                ILoggerFactory loggerFactory,
                CancellationToken ct) =>
            {
                var googleEmail = ctx.User.FindFirst("email")?.Value;
                var googleSub = ctx.User.FindFirst("sub")?.Value;
                var displayName = ctx.User.FindFirst("name")?.Value ?? googleEmail;

                if (string.IsNullOrEmpty(googleEmail) || string.IsNullOrEmpty(googleSub))
                    return Results.Unauthorized();

                var (user, boardId) = await invitationService.AcceptAsync(
                    token, googleEmail, googleSub, displayName!, ct);

                // AcceptAsync has committed — user is now a registered Standard user.
                // Cookie issuance is best-effort: if it fails the user can sign in via
                // the normal flow (/signin → Google → OnTicketReceived recognises them).
                try
                {
                    var identity = new ClaimsIdentity(
                        [
                            new Claim("sub", googleSub),
                            new Claim("email", user.Email),
                            new Claim("name", displayName!),
                            new Claim("user_id", user.Id.ToString()),
                            new Claim("system_role", "standard"),
                        ],
                        CookieAuthenticationDefaults.AuthenticationScheme);
                    await ctx.SignInAsync(
                        CookieAuthenticationDefaults.AuthenticationScheme,
                        new ClaimsPrincipal(identity));
                }
                catch (Exception ex)
                {
                    loggerFactory
                        .CreateLogger(typeof(InviteEndpoints).FullName!)
                        .LogWarning(ex,
                            "Cookie issuance failed for user {UserId} after acceptance; user can sign in via normal flow",
                            user.Id);
                }

                return Results.Ok(new AcceptInviteResponseDto(UserTransforms.ToDto(user), boardId));
            })
            .WithName("AcceptInvite")
