        {
            DeleteCalled = true;
            return Task.CompletedTask;
        }

        public Task UpdateRoleAsync(Guid boardId, Guid userId, BoardRole newRole, IDbTransaction tx)
        {
            UpdatedRole = newRole;
            return Task.CompletedTask;
        }

