            Guid issuedByUserId,
            SystemRole callerRole,
            string frontendBaseUrl,
            Guid? boardId = null,
            BoardRole? boardRole = null,
            CancellationToken cancellationToken = default)
        {
            IssueCalled = true;
            var response = new IssueInviteResponse
            {
                Token = "test-token",
                RedemptionLink = $"{frontendBaseUrl}/accept/test-token",
                ExpiresAt = DateTimeOffset.UtcNow.AddDays(7),
            };
            return Task.FromResult<(IssueInviteResponse, bool)>((response, true));
        }

        public Task<(User User, Guid? BoardId)> AcceptAsync(
            string rawToken,
            string googleEmail,
            string googleSub,
            string displayName,
            CancellationToken cancellationToken = default)
            => throw new NotImplementedException();
    }

    private sealed class FakeUserRepository : IUserRepository
    {
        private readonly IReadOnlyList<User> _users;

        public FakeUserRepository(IReadOnlyList<User>? users = null) => _users = users ?? [];

        public Task<User?> FindByGoogleSubAsync(string googleSub, IDbTransaction? tx = null)
            => Task.FromResult<User?>(null);

        public Task<User?> FindByEmailAsync(string email, IDbTransaction? tx = null)
            => Task.FromResult(_users.FirstOrDefault(u => u.Email == email));

        public Task<User?> FindByIdAsync(Guid userId, IDbTransaction? tx = null)
            => Task.FromResult(_users.FirstOrDefault(u => u.Id == userId));

        public Task<IReadOnlyList<User>> FindByIdsAsync(IEnumerable<Guid> userIds, IDbTransaction? tx = null)
        {
            var ids = userIds.ToHashSet();
            IReadOnlyList<User> result = _users.Where(u => ids.Contains(u.Id)).ToList();
            return Task.FromResult(result);
        }

        public Task InsertAsync(User user, IDbTransaction tx) => Task.CompletedTask;

        public Task LinkGoogleIdentityAsync(Guid userId, string googleSub, IDbTransaction tx)
            => Task.CompletedTask;

        public Task UpdateLastSignInAsync(Guid userId, DateTimeOffset lastSignInAt, IDbTransaction tx)
            => Task.CompletedTask;
    }

    private sealed class FakeCurrentUserService : ICurrentUserServiceFake
    {
        public FakeCurrentUserService(Guid userId, string systemRole)
        {
            UserId = userId;
            SystemRole = systemRole;
            IsAuthenticated = true;
            IsRegistered = true;
        }

        public bool IsAuthenticated { get; }
        public bool IsRegistered { get; }
        public Guid? UserId { get; }
        public string? SystemRole { get; }
        public System.Security.Claims.ClaimsPrincipal Principal { get; } = new();
    }

    private sealed class FakeDbConnectionFactory : IDbConnectionFactory
    {
        public IDbTransaction BeginDeferredTransaction(IDbConnection connection)
            => connection.BeginTransaction();
    }

    public interface ICurrentUserServiceFake : Kanban.Business.Interfaces.ICurrentUserService { }
}

